import{_ as e,o as d,c as l,a2 as n}from"./chunks/framework.YT-FC_Xx.js";const S=JSON.parse('{"title":"内核与协议","description":"","frontmatter":{},"headers":[],"relativePath":"guide/kernels.md","filePath":"guide/kernels.md","lastUpdated":1792771754000}'),r={name:"guide/kernels.md"};function a(s,t,i,o,g,c){return d(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="内核与协议" tabindex="-1">内核与协议 <a class="header-anchor" href="#内核与协议" aria-label="Permalink to &quot;内核与协议&quot;">​</a></h1><p>内核是服务器上真正跑代理协议的程序。面板支持三种内核，一台服务器可以同时装多个，每个入站属于其中一个内核。</p><h2 id="安装内核" tabindex="-1">安装内核 <a class="header-anchor" href="#安装内核" aria-label="Permalink to &quot;安装内核&quot;">​</a></h2><p><strong>服务器</strong> 页 → <strong>内核</strong> 标签 → <strong>安装内核</strong> → 选择服务器和内核。</p><table tabindex="0"><thead><tr><th>内核</th><th>版本</th><th>下载与校验</th></tr></thead><tbody><tr><td>Xray</td><td>默认最新版，可指定</td><td>GitHub Release，用官方校验文件校验</td></tr><tr><td>sing-box</td><td>默认最新版，可指定</td><td>GitHub Release，用 Release 资产的 SHA256 校验</td></tr><tr><td>Snell</td><td>5.0.1（默认）/ 6.0.0（测试版）/ 4.1.1</td><td>只从官方 <code>dl.nssurge.com</code> 下载，使用内置的校验值；6.0.0 没有 armv7 版本</td></tr></tbody></table><p>内核按服务器分组显示。点击内核可以启停、重启、查看日志、更换版本或卸载；服务器重启后内核会自动恢复运行。国内服务器下载慢见 <a href="./agent#国内服务器安装慢">安装服务器 - 国内服务器安装慢</a>。</p><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想要</th><th>选</th></tr></thead><tbody><tr><td>不用域名和证书、通用性最好</td><td>Xray 或 sing-box 的 <strong>VLESS + Reality + Vision</strong></td></tr><tr><td>弱网、高延迟、丢包多的线路</td><td>sing-box 的 <strong>Hysteria2</strong> 或 <strong>TUIC</strong></td></tr><tr><td>抗量子加密（VLESS Encryption）、XHTTP</td><td>Xray</td></tr><tr><td>经中转时让落地看到客户端真实 IP</td><td>Xray（PROXY protocol）</td></tr><tr><td>自动申请证书（ACME）、NaïveProxy、AnyTLS、ShadowTLS</td><td>sing-box</td></tr><tr><td>给 Surge 用 Snell</td><td>sing-box 内置 Snell，或 Snell 内核，区别见 <a href="#snell-用哪个内核">Snell 用哪个内核</a></td></tr></tbody></table><h2 id="协议支持" tabindex="-1">协议支持 <a class="header-anchor" href="#协议支持" aria-label="Permalink to &quot;协议支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th style="text-align:center;">Xray</th><th style="text-align:center;">sing-box</th><th style="text-align:center;">Snell 内核</th></tr></thead><tbody><tr><td>VLESS（TCP / WS / gRPC，Reality / TLS）</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>VLESS + XHTTP</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>VLESS Encryption</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>VMess（TCP / WS / gRPC）</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Trojan（TCP / WS / gRPC）</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Shadowsocks / SS2022</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>SS2022 + ShadowTLS</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Hysteria2（可选端口跳跃）</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>TUIC v5</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>AnyTLS</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>NaïveProxy</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Snell / Snell + ShadowTLS</td><td style="text-align:center;"></td><td style="text-align:center;">✓（1.14+）</td><td style="text-align:center;">✓</td></tr><tr><td>WireGuard</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>SOCKS5 / HTTP 代理</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr></tbody></table><h2 id="功能差异" tabindex="-1">功能差异 <a class="header-anchor" href="#功能差异" aria-label="Permalink to &quot;功能差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th style="text-align:center;">Xray</th><th style="text-align:center;">sing-box</th><th style="text-align:center;">Snell 内核</th></tr></thead><tbody><tr><td>自签证书 / 服务器上的证书文件</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td>自动申请证书（ACME）</td><td style="text-align:center;"></td><td style="text-align:center;">✓（1.14+）</td><td style="text-align:center;">—</td></tr><tr><td>获取真实客户端 IP（PROXY protocol）</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./routing">分流与链式出站</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>作为别的入站的出站节点</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>订阅用户单独凭据</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>入站流量统计（nftables）</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><ul><li>Xray 作出站时只能连接 VLESS / VMess / Trojan / Shadowsocks（不含插件和 ShadowTLS）/ SOCKS5 / HTTP 节点；要连 Hysteria2、TUIC、AnyTLS 等请用 sing-box</li><li>订阅用户单独凭据只对支持的协议有效：Shadowsocks、Snell、WireGuard 在哪个内核上都共用凭据，见 <a href="./subscription-users">凭据、到期与流量</a></li><li>用到 1.14 功能（ACME、内置 Snell、经 Snell 节点出站）的 sing-box 不能换回 1.14 以前的版本，面板会拒绝</li></ul><h2 id="snell-用哪个内核" tabindex="-1">Snell 用哪个内核 <a class="header-anchor" href="#snell-用哪个内核" aria-label="Permalink to &quot;Snell 用哪个内核&quot;">​</a></h2><p>Snell 有两种跑法：装独立的 <strong>Snell 内核</strong>（Surge 官方的 snell-server），或用 <strong>sing-box 1.14 起内置的 Snell</strong>。两者客户端写法一样，客户端可以用 Surge，或 sing-box 1.14 及以上（SFA / SFI / SFM）。</p><table tabindex="0"><thead><tr><th></th><th>sing-box 内置 Snell</th><th>Snell 内核（snell-server）</th></tr></thead><tbody><tr><td>程序</td><td>sing-box 1.14 及以上</td><td>Surge 官方 snell-server 5.0.1 / 6.0.0（测试版）/ 4.1.1，闭源</td></tr><tr><td>客户端版本</td><td>v4、v5、v6 同时可用</td><td>看装的版本：5.x 接受 v4 / v5，6.0.0 只接受 v6</td></tr><tr><td>Snell v6</td><td>✓（PSK 至少 12 位，可选流量整形）</td><td>✓（装 6.0.0 测试版，可选流量整形）</td></tr><tr><td>v5 的 QUIC 代理模式</td><td>不支持，UDP 改走 TCP 转发</td><td>✓（5.x；v6 已取消这个模式）</td></tr><tr><td>ShadowTLS</td><td>sing-box 自己处理，不用额外程序和端口</td><td>另装 shadow-tls，占用一个本机后端端口</td></tr><tr><td>分流、链式出站</td><td>✓</td><td></td></tr><tr><td>和其他协议共用一个内核</td><td>✓</td><td>只跑 Snell</td></tr><tr><td>多用户（userkey）</td><td>不支持，订阅用户共用 PSK</td><td>不支持，订阅用户共用 PSK</td></tr></tbody></table><p>怎么选：</p><ul><li>想要 <strong>v6</strong>、要 <strong>分流 / 链式出站</strong>，或者服务器上已经装了 sing-box：用 <strong>sing-box 内置 Snell</strong></li><li>依赖 <strong>v5 的 QUIC 代理模式</strong>（UDP 走 QUIC），或者只想用 Surge 官方程序：用 <strong>Snell 内核</strong></li><li>想用 Surge 官方的 v6：Snell 内核装 <strong>6.0.0</strong>。注意它是测试版，<strong>只接受 v6 客户端</strong>（v4 / v5 客户端连不上），同一台服务器不能再跑 v4 / v5 入站；需要同时给新老客户端用，就再开一个 sing-box 内置 Snell 入站，或保留 5.0.1</li></ul><p>新建入站时两个内核都能选 <strong>Snell</strong> / <strong>Snell + ShadowTLS</strong> 模板，在 <strong>Snell 版本</strong> 里选客户端版本：</p><ul><li>sing-box 上选 v4 或 v5 时，跑的都是 sing-box 的 v5 服务端（没有 QUIC 模式的 v5 和 v4 协议相同）；选 v6 跑 v6 服务端</li><li>v6 可以选 <strong>流量整形</strong>：默认，或 unshaped（不做整形，更快但更容易被识别）；客户端必须选同样的模式，订阅和分享会自动带上</li><li>Snell 内核上，入站的版本要和服务器安装的 Snell 对得上：v4 入站用 4.x 或 5.x，v5 入站用 5.x，v6 入站用 6.0.0；对不上时保存入站或更换内核版本会被拒绝。服务器装的是 6.0.0 时，新建入站默认就是 v6</li></ul><div class="info custom-block"><p class="custom-block-title">为什么不支持多用户</p><p>sing-box 的 Snell 开启多用户后，只带 PSK、不带 userkey 的客户端会被直接断开，现有链接都会失效。所以面板和 Shadowsocks 一样只用一个 PSK：订阅用户共用凭据，停用后订阅失效，但已经导入的配置仍能连接。</p></div><h3 id="客户端和出站" tabindex="-1">客户端和出站 <a class="header-anchor" href="#客户端和出站" aria-label="Permalink to &quot;客户端和出站&quot;">​</a></h3><ul><li>Snell 没有通用分享链接，<strong>分享</strong> 里显示 Surge 配置行（v6 为 <code>version=6</code>）</li><li><strong>订阅</strong>：Surge 订阅都包含 Snell；sing-box 订阅只给 1.14 及以上的客户端（面板按客户端上报的版本判断），旧客户端遇到 Snell 会整个配置加载失败，所以拿不到；Clash / Mihomo 只支持 Snell v1–v3，不包含</li><li><strong>作为出站节点</strong>：Snell 入站（两种内核搭的都行）可以被 sing-box 1.14 及以上内核的入站选作 <a href="./routing">链式出站或分流去向</a>；Xray 不能连接 Snell</li></ul>',23)])])}const y=e(r,[["render",a]]);export{S as __pageData,y as default};
